import{_ as a,c as e,o as t,a4 as o}from"./chunks/framework.dBUWB6Kx.js";const m=JSON.parse('{"title":"音视频不同步问题","description":"","frontmatter":{},"headers":[],"relativePath":"modules/more/ffmpeg/音视频不同步问题.md","filePath":"modules/more/ffmpeg/音视频不同步问题.md","lastUpdated":1774171177000}'),p={name:"modules/more/ffmpeg/音视频不同步问题.md"},r=o('<h1 id="音视频不同步问题" tabindex="-1">音视频不同步问题 <a class="header-anchor" href="#音视频不同步问题" aria-label="Permalink to &quot;音视频不同步问题&quot;">​</a></h1><h2 id="音频采样率-44-1khz-vs-48khz" tabindex="-1">音频采样率（44.1kHz vs 48kHz） <a class="header-anchor" href="#音频采样率-44-1khz-vs-48khz" aria-label="Permalink to &quot;音频采样率（44.1kHz vs 48kHz）&quot;">​</a></h2><p>Web 视频通常偏好 48kHz 的音频采样率，因为它与视频帧率（如 24fps、30fps 等）更兼容。 如果音频是 44.1kHz 的采样率，浏览器可能需要重新采样为 48kHz，这会导致同步偏差，尤其在解码过程中时间戳被处理不当时。</p><h2 id="转换音频采样率为-48khz" tabindex="-1">转换音频采样率为 48kHz <a class="header-anchor" href="#转换音频采样率为-48khz" aria-label="Permalink to &quot;转换音频采样率为 48kHz&quot;">​</a></h2><p>由于 Web 视频播放对 48kHz 的支持更好，建议转换音频为 48kHz。 ffmpeg -i input.mp4 -c:v copy -ar 48000 -c:a aac output.mp4 -c:v copy：保持视频不变。 -ar 48000：将音频采样率改为 48kHz。 -c:a aac：使用 AAC 编码器。</p><h2 id="修正时间戳" tabindex="-1">修正时间戳 <a class="header-anchor" href="#修正时间戳" aria-label="Permalink to &quot;修正时间戳&quot;">​</a></h2><p>ffmpeg -i input.mp4 -fflags +genpts -c:v copy -c:a copy output.mp4 -fflags +genpts：重新生成时间戳</p><h2 id="确保视频文件是恒定帧率-cfr" tabindex="-1">确保视频文件是恒定帧率（CFR） <a class="header-anchor" href="#确保视频文件是恒定帧率-cfr" aria-label="Permalink to &quot;确保视频文件是恒定帧率（CFR）&quot;">​</a></h2><p>ffmpeg -i input.mp4 -vf &quot;fps=30&quot; -c:v libx264 -preset fast -c:a copy output.mp4 -vf &quot;fps=30&quot;：强制帧率为 30fps。 -c:v libx264：重新编码为 H.264 格式。 -preset fast：快速编码。 -c:a copy：音频保持不变。</p>',9),s=[r];function c(i,f,n,h,l,_){return t(),e("div",null,s)}const u=a(p,[["render",c]]);export{m as __pageData,u as default};
